        println!("{}", tree.root_node().to_sexp());
        println!();
    }
}

use tree_sitter::Parser;

fn parse(source: &str) -> tree_sitter::Tree {
    let mut parser = Parser::new();
    parser
        .set_language(&tree_sitter_matlab::LANGUAGE.into())
        .expect("failed to load tree-sitter-matlab");
    parser.parse(source, None).expect("parse failed")
}

fn named_children<'a>(node: tree_sitter::Node<'a>) -> Vec<tree_sitter::Node<'a>> {
    let mut cursor = node.walk();
    node.children(&mut cursor)
        .filter(|c| c.is_named())
        .collect()
}

#[test]
fn dump_ast() {
    let cases = [
        "figure('GraphicsSmoothing', 'on');\n",
        "set(gca, 'LineStyleOrder', {'-', '--'});\n",
        "get(groot, 'DefaultFigureGraphicsSmoothing');\n",
        "figure(GraphicsSmoothing=\"on\");\n",
        "plot(x, y, 'ColorOrder', c);\n",
        "set(ax, LineStyleOrder={'-','--'});\n",
        "f = figure();\nset(f, 'InvertHardCopy', 'off');\n",
        "feature('DefaultTextFontSmoothing', 'off');\n",
        "set(gcf, 'FontSmoothing');\n",
        "plot(x, y, 'LineWidth', 2);\n",
        "axes('ColorOrder', [1 0 0]);\n",
        "bar(x, y, 'LineStyleOrder', {'-','--',':'});\n",
    ];
    for src in cases {
        let tree = parse(src);
        println!("=== SRC: {src:?}");
        println!("{}", tree.root_node().to_sexp());
        println!();
    }
}

#[test]
fn dump_call_children() {
    let src = "set(gca, 'LineStyleOrder', {'-', '--'});\n";
    let tree = parse(src);
    let root = tree.root_node();
    let mut cursor = root.walk();
    let mut calls: Vec<tree_sitter::Node> = Vec::new();
    fn walk(n: tree_sitter::Node, calls: &mut Vec<tree_sitter::Node>) {
        if n.kind() == "function_call" {
            calls.push(n);
        }
        let mut c = n.walk();
        for ch in n.children(&mut c) {
            walk(ch, calls);
        }
    }
    walk(root, &mut calls);
    for call in &calls {
        println!("CALL {}", src[call.start_byte()..call.end_byte()].to_string());
        let name = call.child_by_field_name("name").unwrap();
        println!("  name kind={} text={}", name.kind(), &src[name.start_byte()..name.end_byte()]);
        let mut c2 = call.walk();
        for (i, ch) in call.children(&mut c2).enumerate() {
            println!(
                "  child[{i}] kind={} named={} text={:?}",
                ch.kind(),
                ch.is_named(),
                &src[ch.start_byte()..ch.end_byte()]
            );
        }
    }
}

