use tree_sitter::Parser;

fn parse(source: &str) -> tree_sitter::Tree {
    let mut parser = Parser::new();
    parser
        .set_language(&tree_sitter_matlab::LANGUAGE.into())
        .expect("failed to load tree-sitter-matlab");
    parser.parse(source, None).expect("parse failed")
}

fn collect_calls<'a>(root: tree_sitter::Node<'a>, out: &mut Vec<tree_sitter::Node<'a>>) {
    if root.kind() == "function_call" {
        out.push(root);
    }
    let mut c = root.walk();
    for ch in root.children(&mut c) {
        collect_calls(ch, out);
    }
}

#[test]
fn dump_args_detail() {
    let cases = [
        "set(gca, 'LineStyleOrder', {'-', '--'});\n",
        "figure(GraphicsSmoothing=\"on\");\n",
        "get(groot, 'DefaultFigureGraphicsSmoothing');\n",
        "set(ax, LineStyleOrder={'-','--'});\n",
        "plot(x, y);\n",
        "axes('ColorOrder', [1 0 0]);\n",
        "h = line(x, y, 'LineStyleOrder', '-');\n",
    ];
    for src in cases {
        let tree = parse(src);
        let mut calls = Vec::new();
        collect_calls(tree.root_node(), &mut calls);
        println!("=== SRC: {src:?}");
        for call in &calls {
            let name = call.child_by_field_name("name").unwrap();
            let mut c2 = call.walk();
            for (i, ch) in call.children(&mut c2).enumerate() {
                let fld = call.field_name_for_child(i as u32).unwrap_or("<none>");
                println!(
                    "  call child[{i}] field={fld} kind={} named={} text={:?}",
                    ch.kind(),
                    ch.is_named(),
                    &src[ch.start_byte()..ch.end_byte()]
                );
                if ch.kind() == "arguments" {
                    let mut c3 = ch.walk();
                    for (j, a) in ch.children(&mut c3).enumerate() {
                        let af = ch.field_name_for_child(j as u32).unwrap_or("<none>");
                        let ns = a
                            .next_sibling()
                            .map(|s| s.kind().to_string())
                            .unwrap_or_else(|| "<end>".to_string());
                        let nns = a
                            .next_named_sibling()
                            .map(|s| src[s.start_byte()..s.end_byte()].to_string())
                            .unwrap_or_else(|| "<end>".to_string());
                        println!(
                            "      arg[{j}] field={af} kind={} named={} text={:?} next_sib_kind={ns} next_named={nns:?}",
                            a.kind(),
                            a.is_named(),
                            &src[a.start_byte()..a.end_byte()]
                        );
                    }
                }
            }
        }
        println!();
    }
}

