/// The callee name of a `function_call` node, if any.
fn call_name<'a>(call: Node<'a>, source: &'a str) -> Option<&'a str> {
    let name = call.child_by_field_name("name")?;
    Some(&source[name.start_byte()..name.end_byte()])
}

/// The `arguments` node of a `function_call`, if the call has arguments.
fn arguments_node<'a>(call: Node<'a>) -> Option<Node<'a>> {
    let mut cursor = call.walk();
    call.children(&mut cursor).find(|c| c.kind() == "arguments")
}
