/// Named children of the call's argument list, with a flag set for positional
/// arguments (those carrying the `argument:` field). Name = value arguments are
/// unnamed and get `false`.
fn named_args<'a>(call: Node<'a>) -> Vec<(Node<'a>, bool)> {
    let mut result = Vec::new();
    let Some(args) = arguments_node(call) else {
        return result;
    };
    let mut cursor = args.walk();
    for (index, child) in args.children(&mut cursor).enumerate() {
        if child.is_named() {
            let is_positional = args.field_name_for_child(index as u32) == Some("argument");
            result.push((child, is_positional));
        }
    }
    result
}
